<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserPasswordAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPasswordAccessor trait.
 *
 * Covers null default, string/VO assignment via withPassword,
 * getPassword/password accessors, and isPasswordChanged with/without original.
 */
class UserPasswordAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPassword creates a new instance with the Password set
     * from a string value, and getPassword returns the primitive string.
     */
    public function testWithPasswordFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserPasswordAccessorUnitTest();

        // Act
        $result = $holder->withPassword('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getPassword());
    }
    /**
     * Asserts that withpassword has access to the value object
     * from a string value, and getPassword returns the primitive string.
     */
    public function testWithPasswordFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserPasswordAccessorUnitTest();

        // Act
        $result = $holder->withPassword('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->password()->value());
    }
    public function testChangedPassword(): void
    {
        // Arrange
        $holder = new ImplWithUserPasswordAccessorUnitTest()->withPassword('cyphered://cypher');
        $original = $holder->withPassword('cyphered://cypher');
        $same = $holder->withPassword('cyphered://cypher');
        $modified = $holder->withPassword('cyphered://ocyphered');

        // Act
        $withSame = $original->isPasswordChanged($same);
        $withDiferent = $original->isPasswordChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserPasswordAccessorUnitTest
{
    use UserPasswordAccessor;
}
